SELECT DISTINCT
    SCENARIO,
    ENTITY,
    DIVISION

FROM  ${DATASETPARTITION("006", "000007", PROCESS($Scenario.code,"01").code, $Scenario.code, "01",,,"(SELECT NULL AS SCENARIO, NULL AS PERIOD, NULL AS ACCOUNT, NULL AS ENTITY, NULL AS CATEGORY, NULL AS DIVISION, NULL AS CUSTOMER, NULL AS PRODUCT, NULL AS RSRCE, 0 AS AMOUNT, NULL AS TEXT_ORIGIN)")} AS T1
UNION ${DATASETPARTITION("006", "000007", PROCESS($Scenario.code,"02").code, $Scenario.code, "02",,,"(SELECT NULL AS SCENARIO, NULL AS PERIOD, NULL AS ACCOUNT, NULL AS ENTITY, NULL AS CATEGORY, NULL AS DIVISION, NULL AS CUSTOMER, NULL AS PRODUCT, NULL AS RSRCE, 0 AS AMOUNT, NULL AS TEXT_ORIGIN)")} AS T2
UNION ${DATASETPARTITION("006", "000007", PROCESS($Scenario.code,"03").code, $Scenario.code, "03",,,"(SELECT NULL AS SCENARIO, NULL AS PERIOD, NULL AS ACCOUNT, NULL AS ENTITY, NULL AS CATEGORY, NULL AS DIVISION, NULL AS CUSTOMER, NULL AS PRODUCT, NULL AS RSRCE, 0 AS AMOUNT, NULL AS TEXT_ORIGIN)")} AS T3
UNION ${DATASETPARTITION("006", "000007", PROCESS($Scenario.code,"04").code, $Scenario.code, "04",,,"(SELECT NULL AS SCENARIO, NULL AS PERIOD, NULL AS ACCOUNT, NULL AS ENTITY, NULL AS CATEGORY, NULL AS DIVISION, NULL AS CUSTOMER, NULL AS PRODUCT, NULL AS RSRCE, 0 AS AMOUNT, NULL AS TEXT_ORIGIN)")} AS T4
UNION ${DATASETPARTITION("006", "000007", PROCESS($Scenario.code,"05").code, $Scenario.code, "05",,,"(SELECT NULL AS SCENARIO, NULL AS PERIOD, NULL AS ACCOUNT, NULL AS ENTITY, NULL AS CATEGORY, NULL AS DIVISION, NULL AS CUSTOMER, NULL AS PRODUCT, NULL AS RSRCE, 0 AS AMOUNT, NULL AS TEXT_ORIGIN)")} AS T5
UNION ${DATASETPARTITION("006", "000007", PROCESS($Scenario.code,"06").code, $Scenario.code, "06",,,"(SELECT NULL AS SCENARIO, NULL AS PERIOD, NULL AS ACCOUNT, NULL AS ENTITY, NULL AS CATEGORY, NULL AS DIVISION, NULL AS CUSTOMER, NULL AS PRODUCT, NULL AS RSRCE, 0 AS AMOUNT, NULL AS TEXT_ORIGIN)")} AS T6
UNION ${DATASETPARTITION("006", "000007", PROCESS($Scenario.code,"07").code, $Scenario.code, "07",,,"(SELECT NULL AS SCENARIO, NULL AS PERIOD, NULL AS ACCOUNT, NULL AS ENTITY, NULL AS CATEGORY, NULL AS DIVISION, NULL AS CUSTOMER, NULL AS PRODUCT, NULL AS RSRCE, 0 AS AMOUNT, NULL AS TEXT_ORIGIN)")} AS T7
UNION ${DATASETPARTITION("006", "000007", PROCESS($Scenario.code,"08").code, $Scenario.code, "08",,,"(SELECT NULL AS SCENARIO, NULL AS PERIOD, NULL AS ACCOUNT, NULL AS ENTITY, NULL AS CATEGORY, NULL AS DIVISION, NULL AS CUSTOMER, NULL AS PRODUCT, NULL AS RSRCE, 0 AS AMOUNT, NULL AS TEXT_ORIGIN)")} AS T8
UNION ${DATASETPARTITION("006", "000007", PROCESS($Scenario.code,"09").code, $Scenario.code, "09",,,"(SELECT NULL AS SCENARIO, NULL AS PERIOD, NULL AS ACCOUNT, NULL AS ENTITY, NULL AS CATEGORY, NULL AS DIVISION, NULL AS CUSTOMER, NULL AS PRODUCT, NULL AS RSRCE, 0 AS AMOUNT, NULL AS TEXT_ORIGIN)")} AS T9
UNION ${DATASETPARTITION("006", "000007", PROCESS($Scenario.code,"10").code, $Scenario.code, "10",,,"(SELECT NULL AS SCENARIO, NULL AS PERIOD, NULL AS ACCOUNT, NULL AS ENTITY, NULL AS CATEGORY, NULL AS DIVISION, NULL AS CUSTOMER, NULL AS PRODUCT, NULL AS RSRCE, 0 AS AMOUNT, NULL AS TEXT_ORIGIN)")} AS T10
UNION ${DATASETPARTITION("006", "000007", PROCESS($Scenario.code,"11").code, $Scenario.code, "11",,,"(SELECT NULL AS SCENARIO, NULL AS PERIOD, NULL AS ACCOUNT, NULL AS ENTITY, NULL AS CATEGORY, NULL AS DIVISION, NULL AS CUSTOMER, NULL AS PRODUCT, NULL AS RSRCE, 0 AS AMOUNT, NULL AS TEXT_ORIGIN)")} AS T11
UNION ${DATASETPARTITION("006", "000007", PROCESS($Scenario.code,"12").code, $Scenario.code, "12",,,"(SELECT NULL AS SCENARIO, NULL AS PERIOD, NULL AS ACCOUNT, NULL AS ENTITY, NULL AS CATEGORY, NULL AS DIVISION, NULL AS CUSTOMER, NULL AS PRODUCT, NULL AS RSRCE, 0 AS AMOUNT, NULL AS TEXT_ORIGIN)")} AS T12


WHERE 
    SCENARIO=${$Scenario.code}
    AND AMOUNT <> 0
    AND TEXT_ORIGIN = 'AW006_RV_AMOUNT'

